import {validateMemory,comparisonFor,filterMemory,escapeHtml as esc} from './memory-model.js';

const $=id=>document.getElementById(id);
const date=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const label={seen:'Seen in this snapshot',unavailable:'Source unavailable',not_seen:'Not seen in this scan'};
const sources={endpoint:'Endpoint inventory',dns:'Mail DNS',m365:'Microsoft 365 apps',inventory:'Owner inventory',endpoints:'ERP web endpoints'};
const sourceLabel={complete:'Complete',error:'Unavailable',not_configured:'Not configured',absent:'Not in report'};
const tag=(value,kind='')=>`<span class="memory-tag ${kind}">${esc(value)}</span>`;
let memory=null,selected=1,before=0,tab='changes',query='',timer=null;

function message(value=''){$('memory-status').className=value?'memory-status':'';$('memory-status').textContent=value;}
function stopReplay(){clearInterval(timer);timer=null;$('replay-memory').textContent='Replay the story ↻';}
function current(){return memory.views[selected];}
function delta(){return selected?comparisonFor(memory,before,selected):null;}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setSnapshot(index,focus=false){if(!Number.isInteger(index)||index<0||index>=memory.runs.length)return;selected=index;before=Math.max(0,index-1);query='';render();if(focus)$('timeline').querySelector(`[data-snapshot="${index}"]`)?.focus();}

function render(){
  if(!memory)return;
  const run=memory.runs[selected],view=current(),c=delta(),demo=memory.company.mode==='demo';
  $('company-sidebar').textContent=memory.company.name;
  document.querySelector('.workspace-avatar').textContent=memory.company.name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
  $('memory-mode').textContent=demo?'Fictional '+memory.company.name:'Saved company history';
  $('memory-mode').className='mode-badge'+(demo?'':' live');
  $('memory-notice').innerHTML=demo?'<span class="sample-icon">◈</span><span><b>Fictional company history.</b> These saved snapshots were processed by the company memory engine. Replay explores the sample; it does not run a scan.</span>':'<span class="sample-icon">◇</span><span><b>Saved company history.</b> This viewer is read-only. Opening a history file does not alter its saved database or upload its contents.</span>';
  $('timeline').innerHTML=memory.runs.map((r,i)=>`<button class="snapshot-button" data-snapshot="${i}" aria-pressed="${i===selected}"><small>${esc(date(r.generated_at))} · UTC</small><span class="snapshot-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(r.label||`Snapshot ${i+1}`)}</strong><span>${r.report.systems.length} systems seen · ${memory.views[i].counts.remembered} remembered</span></button>`).join('');
  $('timeline').style.gridTemplateColumns=memory.runs.length>3?'repeat(auto-fit,minmax(220px,1fr))':'';
  const changes=c?c.system_changes.length+c.relationship_changes.length:0;
  $('memory-body').innerHTML=`<div class="memory-kpis"><div class="memory-kpi"><span>Systems remembered</span><strong>${view.counts.remembered}</strong><small>Known through this snapshot</small></div><div class="memory-kpi"><span>Seen in this snapshot</span><strong>${view.counts.seen}</strong><small>Current collection evidence</small></div><div class="memory-kpi"><span>${selected?'System & link changes':'Starting baseline'}</span><strong>${selected?changes:memory.runs[0].report.systems.length}</strong><small>${selected?'Compared with '+date(memory.runs[before].generated_at):'The first retained company view'}</small></div><div class="memory-kpi ${view.counts.unavailable+view.counts.not_seen?'warn':''}"><span>Visibility gaps</span><strong>${view.counts.unavailable+view.counts.not_seen}</strong><small>${view.counts.unavailable} source unavailable · ${view.counts.not_seen} not seen</small></div></div><div class="memory-grid"><section class="panel" aria-label="Company history"><div class="memory-tabs" role="tablist" aria-label="Memory views">${[['changes','What changed'],['systems','Remembered systems'],['sources','Source visibility']].map(([id,name])=>`<button class="memory-tab" id="tab-${id}" role="tab" data-tab="${id}" aria-selected="${tab===id}" aria-controls="memory-panel" tabindex="${tab===id?'0':'-1'}">${name}</button>`).join('')}</div><div id="memory-panel" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='changes'?renderChanges():tab==='systems'?renderSystems():renderSources()}</div></section><aside>${renderContext()}</aside></div>`;
  $('memory-footer').textContent=`${memory.company.name} · ${memory.scope.id} · Scope revision ${memory.scope.revision} · Snapshot ${selected+1} of ${memory.runs.length}`;
  $('download-memory').disabled=false;$('replay-memory').disabled=false;$('replay-memory').hidden=!demo;
}

function renderChanges(){
  if(!selected)return `<div class="memory-baseline"><div class="eyebrow">THE FIRST COMPANY MEMORY</div><h2>${current().counts.remembered} systems. One retained starting point.</h2><p>Glinx keeps the original systems, owner claims, connections, and discovery evidence. Later scans can build on this history.</p><p>${esc(memory.runs[0].narrative||'Select a later snapshot to compare changes with this baseline.')}</p><div class="memory-actions">${memory.runs.length>1?'<button class="button primary" data-next="1">See the next snapshot →</button>':''}<button class="button" data-tab="systems">Inspect the baseline</button></div></div>`;
  const c=delta();
  const options=memory.runs.slice(0,selected).map((r,i)=>`<option value="${i}" ${before===i?'selected':''}>${esc(date(r.generated_at))} · Snapshot ${i+1}</option>`).join('');
  let cards=c.source_changes.map(s=>`<article class="change-card ${s.after==='error'||s.after==='absent'?'warn':''}"><span class="change-icon">⌁</span><div><span class="change-kind">Source status changed</span><h3>${esc(s.name)}</h3><div class="change-delta"><del>${esc(sourceLabel[s.before])}</del><span>→</span><ins>${esc(sourceLabel[s.after])}</ins></div><p>Source status describes visibility. Earlier system evidence stays in company memory.</p></div><button class="text-button" data-tab="sources">Inspect source ↗</button></article>`).join('');
  cards+=c.system_changes.map(change=>{
    const item=current().systems.find(s=>s.record.id===change.id),warn=['unavailable','not_seen'].includes(change.kind);
    const owner=change.fields.find(f=>f.field==='owner');
    const titles={added:'Added to company memory',changed:owner?'Owner claim updated':'System claims updated',evidence_changed:'Supporting evidence changed',seen_again:'Seen again',unavailable:'Earlier evidence retained',not_seen:'Follow-up needed'};
    const description={added:'Newly disclosed to Glinx. Discovery time does not establish when the system was installed.',changed:'The latest supplied claim is retained alongside its earlier history.',evidence_changed:'The source statement changed. Open the history to compare both records.',seen_again:'This system appears in the selected scan after a visibility gap.',unavailable:'The source that previously identified this system is unavailable. Its latest known evidence remains visible.',not_seen:'The relevant source completed, but this system is absent from the selected scan. Removal has not been established.'};
    const fields=change.fields.filter(f=>['owner','name','category','status'].includes(f.field));
    return `<article class="change-card ${warn?'warn':''}"><span class="change-icon">${change.kind==='added'?'+':warn?'?':'↻'}</span><div><span class="change-kind">${titles[change.kind]}</span><h3>${esc(change.name)}</h3>${fields.map(f=>`<div class="change-delta"><del>${esc(f.before||'Unassigned')}</del><span>→</span><ins>${esc(f.after||'Unassigned')}</ins></div>`).join('')}<p>${description[change.kind]}</p>${warn?`<p>Last seen ${esc(date(item.last_seen))} · ${esc(item.unavailable_sources.map(s=>sources[s]||s).join(', ')||'Completed source')}</p>`:''}</div><button class="text-button" data-system="${esc(change.id)}">See evidence ↗</button></article>`;
  }).join('');
  cards+=c.relationship_changes.map(change=>{
    const link=current().relationships.find(r=>r.record.id===change.id).record;
    const name=id=>current().systems.find(s=>s.record.id===id)?.record.name||id;
    return `<article class="change-card"><span class="change-icon">⇄</span><div><span class="change-kind">${change.kind==='added'?'Connection added to memory':change.kind==='not_seen'?'Connection not seen':'Connection claim changed'}</span><h3>${esc(name(link.source))} → ${esc(name(link.target))}</h3><p>${esc(link.label)} · ${esc(link.status)}</p><p>${esc(link.evidence)}</p></div><button class="text-button" data-system="${esc(link.source)}">See evidence ↗</button></article>`;
  }).join('');
  return `<div class="memory-toolbar"><h2>Changes with evidence</h2><label>Compare with <select id="compare-before" aria-label="Earlier snapshot">${options}</select></label></div><div class="change-list">${cards||'<div class="memory-blank">No meaningful system, connection, or source-status changes. Refreshed collection timestamps do not count as company changes.</div>'}</div><div class="memory-note"><strong>History is preserved.</strong> Owner and integration statements retain their evidence status. A missing record is never automatically treated as a deleted system.</div>`;
}

function systemRows(){return filterMemory(current(),query).map(s=>`<tr><td><button class="system-name" data-system="${esc(s.record.id)}">${esc(s.record.name)}</button><small>${esc(s.record.attributes?.business_function||s.record.category)}</small></td><td>${esc(s.record.owner||'Unassigned')}<small>Latest supplied owner claim</small></td><td>${tag(label[s.visibility],s.visibility==='seen'?'':'warn')}<small>Last seen ${esc(date(s.last_seen))}</small></td><td><button class="text-button" data-system="${esc(s.record.id)}">${s.history.length} snapshots ↗</button></td></tr>`).join('');}
function renderSystems(){return `<div class="memory-toolbar"><input class="memory-search" id="memory-search" type="search" aria-label="Search remembered systems" placeholder="Search systems, owners, or evidence visibility…" value="${esc(query)}"></div><div class="table-scroll"><table class="memory-table"><thead><tr><th>SYSTEM</th><th>OWNER CLAIM</th><th>VISIBILITY</th><th>HISTORY</th></tr></thead><tbody id="memory-rows">${systemRows()}</tbody></table><div id="memory-empty" class="memory-blank" ${filterMemory(current(),query).length?'hidden':''}>No systems match this search.</div></div><div class="memory-note">${current().counts.remembered} systems known through this snapshot. Legacy product records may combine multiple installations; native instance identities are the next development step.</div>`;}
function renderSources(){return memory.runs[selected].report.collectors.map(c=>`<article class="memory-source"><header><h3>${esc(c.name)}</h3>${tag(sourceLabel[c.status],c.status==='error'?'warn':c.status==='not_configured'?'neutral':'')}</header><p>${esc(c.detail)}</p><p>${c.count} supplied findings · ${esc(date(memory.runs[selected].generated_at))}</p></article>`).join('')+`<div class="memory-note"><strong>Collection boundary:</strong> ${esc(memory.scope.description)} Source completion does not measure total company coverage.</div>`;}

function renderContext(){
  const v=current(),hasGap=v.counts.unavailable+v.counts.not_seen;
  const title=hasGap?'Memory survives a visibility gap.':selected?'A growing model of the company.':'Understanding begins with a baseline.';
  const copy=hasGap?`${v.counts.remembered} systems remain in memory. ${v.counts.seen} are seen in this snapshot. The rest retain their previous evidence, with a clear visibility label.`:selected?'Each new snapshot adds context to the earlier picture. Ownership, relationships, and supporting evidence remain traceable.':'Discovery records what it can see. Company memory retains that view so future observations have a reference point.';
  return `<div class="memory-context"><div class="eyebrow">WHAT GLINX NOW KNOWS</div><h2>${title}</h2><p>${copy}</p>${hasGap?'<ul><li>Restore access to the failed source.</li><li>Ask the system owner about missing inventory entries.</li><li>Collect another snapshot to check again.</li></ul>':'<p>Open a system to inspect the original evidence and its later history.</p>'}<div class="context-divider"><div class="eyebrow">COMPANY PURPOSE</div><p>${esc(memory.company.purpose||'A company owner has not supplied a purpose yet.')}</p></div><div class="context-divider"><div class="eyebrow">THE NEXT STEP</div><p>Distinct system identities, then one read-only ERP connector and an operating metric. This memory view is the foundation for those capabilities.</p></div></div><div class="memory-note">${memory.company.mode==='demo'?'This sample history comes from the working local database implementation. The hosted viewer explores an exported copy.':'Imported history stays in this tab. Its underlying local database remains the persistent record.'}</div>`;
}

function openSystem(id){
  const item=current().systems.find(s=>s.record.id===id);if(!item)return;
  const history=memory.runs.slice(0,selected+1).map((run,i)=>({run,index:i,system:run.report.systems.find(s=>s.id===id)})).filter(entry=>entry.system||item.history.some(runId=>memory.runs.findIndex(r=>r.run_id===runId)<=entry.index));
  const related=current().relationships.filter(r=>r.record.source===id||r.record.target===id);
  $('memory-detail-body').innerHTML=`<div class="dialog-head"><span class="eyebrow">EVIDENCE THROUGH TIME</span><button class="icon-button" id="close-memory-details" aria-label="Close system history">×</button></div><h2 id="memory-detail-title">${esc(item.record.name)}</h2>${tag(label[item.visibility],item.visibility==='seen'?'':'warn')}<div class="memory-note">First seen ${esc(date(item.first_seen))}. Last seen ${esc(date(item.last_seen))}. ${item.history.length} snapshots contain evidence for this product record.</div>${history.map(({run,index,system})=>`<article class="memory-history-card"><h3>${esc(date(run.generated_at))} · Snapshot ${index+1}</h3>${system?`<p><b>Owner claim:</b> ${esc(system.owner||'Unassigned')} · ${esc(system.status)} system evidence</p>${system.evidence.map(e=>`<div class="evidence-card"><div class="evidence-top"><b>${esc(sources[e.source]||e.source)}</b>${tag(e.status,'neutral')}</div><p>${esc(e.summary)}</p><small>${esc(e.locator||'Source metadata')}<br>${esc(e.observed_at)} · Evidence ${esc(e.id)}</small></div>`).join('')}`:`<p>${esc(label[memory.views[index].systems.find(s=>s.record.id===id).visibility])}. Earlier evidence remains in memory; deletion has not been established.</p>`}</article>`).join('')}${related.length?'<h3>Remembered connection claims</h3>'+related.map(r=>`<article class="memory-history-card"><h3>${esc(r.record.label)}</h3>${tag(r.record.status,'neutral')}<p>${esc(r.record.evidence)}</p><small>${r.visibility==='seen'?'Present in selected snapshot':'Not seen in selected snapshot; retained from earlier evidence'}</small></article>`).join(''):''}<div class="memory-note">Reports and exports are supplied evidence, not signed attestations. Detection scores describe rule strength. They do not establish active use, operational health, or verified ownership.</div>`;
  $('close-memory-details').onclick=()=>$('memory-details').close();$('memory-details').showModal();
}

$('timeline').onclick=e=>{const button=e.target.closest('[data-snapshot]');if(button&&memory){stopReplay();setSnapshot(Number(button.dataset.snapshot),true);}};
$('memory-body').onclick=e=>{const system=e.target.closest('[data-system]'),button=e.target.closest('[data-tab]'),next=e.target.closest('[data-next]');if(system){stopReplay();openSystem(system.dataset.system);}else if(button){tab=button.dataset.tab;render();$('tab-'+tab)?.focus();}else if(next){stopReplay();setSnapshot(Number(next.dataset.next));}};
$('memory-body').onchange=e=>{if(e.target.id==='compare-before'){before=Number(e.target.value);render();$('compare-before')?.focus();}};
$('memory-body').oninput=e=>{if(e.target.id==='memory-search'){query=e.target.value;$('memory-rows').innerHTML=systemRows();$('memory-empty').hidden=filterMemory(current(),query).length>0;}};
$('memory-body').onkeydown=e=>{const button=e.target.closest('[role="tab"]');if(button&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=['changes','systems','sources'];let index=tabs.indexOf(tab);index=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;tab=tabs[index];render();$('tab-'+tab).focus();}};
$('replay-memory').onclick=()=>{if(!memory)return;if(timer){stopReplay();message('Story paused. Select any snapshot to continue exploring.');return;}message('Replaying saved sample snapshots.');tab='changes';setSnapshot(0);$('replay-memory').textContent='Pause story □';timer=setInterval(()=>{if(selected+1>=memory.runs.length){stopReplay();message('Story complete. Open any change to inspect its evidence.');}else setSnapshot(selected+1);},3500);};
$('download-memory').onclick=()=>{if(memory)download('glinx-company-memory.json',memory);};
$('open-history').onclick=()=>$('history-file').click();
$('history-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15_000_000)throw new Error('History files must be smaller than 15 MB.');const loaded=validateMemory(JSON.parse(await file.text()));stopReplay();memory=loaded;tab='changes';setSnapshot(Math.min(1,memory.runs.length-1));message('Opened saved history. This read-only copy stays in this tab.');}catch(error){message(error.message||'Unable to open history. Your current view is preserved.');}finally{e.target.value='';}};
$('memory-details').onclick=e=>{if(e.target===$('memory-details')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
window.addEventListener('pagehide',stopReplay);
async function boot(){try{const response=await fetch('./memory-demo.json',{cache:'no-store'});if(!response.ok)throw new Error('Saved company history is unavailable.');const raw=await response.text();if(new TextEncoder().encode(raw).length>15_000_000)throw new Error('History exceeds the browser size limit.');memory=validateMemory(JSON.parse(raw));setSnapshot(Math.min(1,memory.runs.length-1));}catch(error){$('memory-body').innerHTML='<div class="error-state"><h2>Company history could not be opened.</h2><p>Reload this page or open a valid company memory export. No sample will replace a failed history.</p></div>';message(error.message||'History could not be loaded.');}}
boot();
